"""matplotlib.sphinxext.mathmpl — ``:mathmpl:`` Sphinx role stub.

Renders inline math expressions in Sphinx docs as PNGs via matplotlib's
mathtext. The shim emits a placeholder."""


def setup(app=None):
    return {'version': '0.0-shim', 'parallel_read_safe': True}


def fontset_choice(arg):
    """Validator used by the directive's ``:fontset:`` option."""
    if arg in ('cm', 'stix', 'stixsans', 'dejavusans', 'dejavuserif'):
        return arg
    raise ValueError(f'unknown fontset: {arg!r}')


def latex_math(role, rawtext, text, lineno, inliner, options=None, content=None):
    """The :math: role implementation. Returns empty nodes — Sphinx
    won't render any math from this shim."""
    return [], []


def math_role(role, rawtext, text, lineno, inliner, options=None, content=None):
    return latex_math(role, rawtext, text, lineno, inliner, options, content)


class MathDirective:
    has_content = True
    def run(self):
        return []


def depart_latex_math_html(self, node):
    pass


def visit_latex_math_html(self, node):
    pass


# ─── Added: missing public renderers ────────────────────────────────


def latex2png(text, fontset='cm', fontsize=12, dpi=100):
    """Render a LaTeX math string to a PNG image array. The shim returns
    a 1x1 transparent placeholder."""
    import numpy as _np
    return _np.zeros((1, 1, 4), dtype=_np.uint8)


def latex2html(node, source):
    """Render LaTeX math as HTML (via embedded image). Returns an
    empty string in the shim."""
    return ''
